import functools

def retry(times):
    def deco(f):
        @functools.wraps(f)
        def wrapper(*a, **k):
            last = None
            for attempt in range(1, times + 1):
                try:
                    return f(*a, **k)
                except ValueError as e:
                    last = e
                    print(f"attempt {attempt} failed")
            raise last
        return wrapper
    return deco

calls = {"n": 0}

@retry(3)
def flaky():
    calls["n"] += 1
    if calls["n"] < 3:
        raise ValueError("boom")
